# é o último `UPDATE` que a linha aceita.
VERSAO_E_PEDRA = """
CREATE OR REPLACE FUNCTION jornadas_versao_publicada_e_pedra()
RETURNS trigger AS $$
BEGIN
    IF OLD.publicada_em IS NOT NULL THEN
        RAISE EXCEPTION
            'jornadas: versao publicada e imutavel (id=%). Publique uma versao NOVA.',
            OLD.id;
    END IF;
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
"""

PASSO_E_PEDRA = """
CREATE OR REPLACE FUNCTION jornadas_passo_publicado_e_pedra()
RETURNS trigger AS $$
DECLARE
    publicada timestamptz;
BEGIN
    SELECT jv.publicada_em INTO publicada
      FROM jornadas_jornadaversao jv
     WHERE jv.id = OLD.jornada_versao_id;
    IF publicada IS NOT NULL THEN
        RAISE EXCEPTION
            'jornadas: versao publicada e imutavel; o passo % pertence a ela. Publique uma versao NOVA.',
            OLD.id;
    END IF;
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
"""

TEXTO_E_PEDRA = """
CREATE OR REPLACE FUNCTION jornadas_texto_publicado_e_pedra()
RETURNS trigger AS $$
DECLARE
    publicada timestamptz;
BEGIN
    SELECT jv.publicada_em INTO publicada
      FROM jornadas_passo p
      JOIN jornadas_jornadaversao jv ON jv.id = p.jornada_versao_id
     WHERE p.id = OLD.passo_id;
    IF publicada IS NOT NULL THEN
        RAISE EXCEPTION
            'jornadas: versao publicada e imutavel; o texto % pertence a ela. Publique uma versao NOVA.',
            OLD.id;
    END IF;
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
"""

